// lib/clickhouse/runClickhouseTriage.ts
// Decision point: mock vs real ClickHouse execution.
// For public repo / no credentials, return mock metrics,
// BUT always return REAL SQL generated by sqlBuilder (so curl proves wiring).
//
// ✅ Generator is source of truth:
// - runner returns CANONICAL metricsJson only (no spreads, no legacy keys)
// - route should NOT normalize/reshape

import { buildClickhouseSql } from "./sqlBuilder";
import { runMockClickhouseTriage } from "./runMockClickhouseTriage";
import { CANON } from "@/lib/schema/canonical";

export type ClickhouseTriageInputs = {
  partner: string;

  // Core scope filters (service REQUIRED; no "all")
  service: string; // canon only (live|vod|dvr|eas|live_ott|app_backend)
  region: string; // all|<canon>
  pop: string; // all|<canon>

  // Generator schema dims
  contentType: string; // all|manifest|segment|api
  uaFamily: string; // all|stb|mobile|web|smart_tv|console

  windowMinutes: number;
  debug: boolean;
};

// Canonical SQL shape (include params so runner can execute later)
export type SqlPayload = { queries: string[]; params?: Record<string, any> };

export type ClickhouseTriageResult = {
  summary: string;
  metricsJson: any;
  evidence?: any;
  sql?: SqlPayload;

  // Legacy compatibility
  summaryText?: string;
};

function isCanon(x: string, allowed: readonly string[]) {
  return allowed.includes(x);
}

function assertCanonicalMetrics(metricsJson: any) {
  if (!metricsJson || typeof metricsJson !== "object") {
    throw new Error("runClickhouseTriage: metricsJson missing");
  }

  const required = ["totalRequests", "p95TtmsMs", "error5xxCount", "errorRatePct"];
  for (const k of required) {
    if (!(k in metricsJson)) {
      throw new Error(`runClickhouseTriage: non-canonical metricsJson (missing ${k})`);
    }
  }

  // Ensure timeseries exists to prevent UI crashes
  const t = metricsJson.timeseries;
  const timeseries =
    t && typeof t === "object" && Array.isArray(t.points)
      ? t
      : { bucketSeconds: null, startTs: null, endTs: null, points: [] };

  // Ensure debug is an object (never null)
  const debugIn = metricsJson.debug;
  const debug = debugIn && typeof debugIn === "object" ? debugIn : {};

  // ✅ Strip legacy keys by returning ONLY canonical shape
  return {
    totalRequests: Number(metricsJson.totalRequests) || 0,
    p50TtmsMs: metricsJson.p50TtmsMs == null ? null : Number(metricsJson.p50TtmsMs),
    p95TtmsMs: metricsJson.p95TtmsMs == null ? null : Number(metricsJson.p95TtmsMs),
    p99TtmsMs: metricsJson.p99TtmsMs == null ? null : Number(metricsJson.p99TtmsMs),
    error5xxCount: Number(metricsJson.error5xxCount) || 0,
    errorRatePct: Number(metricsJson.errorRatePct) || 0,
    timeseries,
    debug,
  };
}

export async function runClickhouseTriage(
  inputs: ClickhouseTriageInputs
): Promise<ClickhouseTriageResult> {
  const partner = String(inputs.partner || "").trim().toLowerCase();
  const service = String(inputs.service || "").trim().toLowerCase();
  const region = String(inputs.region || "all").trim().toLowerCase();
  const pop = String(inputs.pop || "all").trim().toLowerCase();
  const contentType = String(inputs.contentType || "all").trim().toLowerCase();
  const uaFamily = String(inputs.uaFamily || "all").trim().toLowerCase();

  if (!partner || !isCanon(partner, CANON.partners as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid partner '${inputs.partner}'`);
  }
  if (!service || service === "all" || !isCanon(service, CANON.services as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid service '${inputs.service}'`);
  }
  if (region !== "all" && !isCanon(region, CANON.regions as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid region '${inputs.region}'`);
  }
  if (pop !== "all" && !isCanon(pop, CANON.pops as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid pop '${inputs.pop}'`);
  }
  if (contentType !== "all" && !isCanon(contentType, CANON.contentTypes as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid contentType '${inputs.contentType}'`);
  }
  if (uaFamily !== "all" && !isCanon(uaFamily, CANON.uaFamilies as readonly string[])) {
    throw new Error(`runClickhouseTriage: invalid uaFamily '${inputs.uaFamily}'`);
  }

  const win = Number(inputs.windowMinutes);
  if (!Number.isFinite(win) || win <= 0) {
    throw new Error(`runClickhouseTriage: invalid windowMinutes '${inputs.windowMinutes}'`);
  }

  // Dataset is backfilled/old → anchor window to max(ts) by default
  const anchorToMaxTs = true;

  // ✅ ALWAYS build canonical SQL first
  const built = buildClickhouseSql({
    partner,
    service,
    region,
    pop,
    contentType,
    uaFamily,
    windowMinutes: win,
    anchorToMaxTs,
  } as any);

  // Later: swap this for real ClickHouse execution.
  const raw = await runMockClickhouseTriage({
    ...inputs,
    partner,
    service,
    region,
    pop,
    contentType,
    uaFamily,
    windowMinutes: win,
  });

  const summary = String(raw?.summary ?? raw?.summaryText ?? "");
  const evidence = raw?.evidence ?? undefined;

  // ✅ Require canonical metricsJson from mock (generator is truth)
  const baseMetrics = raw?.metricsJson ?? raw ?? {};
  const metricsJson = assertCanonicalMetrics(baseMetrics);

  // ✅ stamp runner version + meta
  metricsJson.debug = {
    ...(metricsJson.debug || {}),
    __runnerVersion: "runclickhouse-vSTRICT-001",
    partner,
    service,
    region,
    pop,
    contentType,
    uaFamily,
    windowMinutes: win,
    anchorToMaxTs,
  };

  const finalSummary =
    summary ||
    `Triage: partner=${partner} service=${service} region=${region} pop=${pop} win=${win}m ct=${contentType} ua=${uaFamily}\n` +
      `requests=${Number(metricsJson.totalRequests).toLocaleString()} p95=${Math.round(
        Number(metricsJson.p95TtmsMs)
      )}ms 5xx=${Number(metricsJson.error5xxCount).toLocaleString()} (${Number(
        metricsJson.errorRatePct
      ).toFixed(2)}%)`;

  return {
    summary: finalSummary,
    summaryText: finalSummary,
    metricsJson,
    evidence,
    sql: { queries: built.queries, params: built.params },
  };
}